import assert from 'node:assert/strict';
import {mkdtempSync,openSync,writeSync,readSync,fsyncSync,closeSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {ExecutionBudget,ExecutionLimitError} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/execution-budget.ts';
import {RuntimeValues} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-values.ts';
import {RuntimeTypeRegistry} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-type-registry.ts';
import {RuntimeExceptionExecution} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-exception-execution.ts';
import {RuntimeCodecRegistry} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-codec-registry.ts';
import {RuntimeCodecRecovery} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-codec-recovery.ts';
import {PythonEncodeError} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/encode-error.ts';
import {PythonDecodeError} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/decode-error.ts';
import {PythonRuntimeError} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/error.ts';
const directory=mkdtempSync(join(tmpdir(),'codec-preparation-'));
const fd=openSync(join(directory,'events'),'w+');
const rows=[];
try{
for(const operation of ['encode','decode'])for(const outcome of ['return','ordinary','guest','fatal'])for(const cancel of [false,true]){
 const abort=new AbortController(),meter=new ExecutionBudget({maxSteps:100000,maxAllocatedBytes:1000000,signal:abort.signal});
 const values=new RuntimeValues(meter),types=new RuntimeTypeRegistry(values,{hash:()=>0n,equal:(a,b)=>a===b},meter);
 const exceptions=new RuntimeExceptionExecution(types,values,meter),registry=new RuntimeCodecRegistry(values,meter);
 const text=values.string('\ud800'),source=operation==='encode'?text:values.bytes(Uint8Array.of(255));
 const fault=operation==='encode'?new PythonEncodeError('utf-8',text.value,0,1,'surrogates not allowed'):new PythonDecodeError('utf-8',Uint8Array.of(255),0,1,'invalid start byte');
 const ordinary=new Error('service failed'),guest=exceptions.prepare(new PythonRuntimeError('ValueError','guest service failed')),fatal=new ExecutionLimitError('allocation');
 const answer=values.tuple([values.string('?'),values.integer(-1)]);
 let calls=0,handlers=0;
 const context={isCallable:()=>true,isException:(error,name)=>exceptions.matches(error,name),call(){handlers++;return answer;},prepareException(error,retained){
  calls++;const prepared=exceptions.prepare(error,retained);
  const data=Buffer.from(JSON.stringify({operation,outcome,cancel})+'\n');
  const position=writeSync(fd,data);fsyncSync(fd);
  assert.equal(position,data.length);
  if(cancel)abort.abort();
  if(outcome==='ordinary')throw ordinary;if(outcome==='guest')throw guest;if(outcome==='fatal')throw fatal;
  return prepared;
 }};
 registry.registerError('custom',values.cell({}),context);
 const recovery=new RuntimeCodecRecovery(registry,'custom',source,context);
 let failure,result;try{result=operation==='encode'?recovery.encode(fault):recovery.decode(fault);}catch(error){failure=error;}
 assert.equal(calls,1);assert.equal(handlers,!cancel&&outcome==='return'?1:0);
 if(outcome==='fatal')assert.equal(failure,fatal);
 else if(cancel)assert.equal(failure?.reason,'cancelled');
 else if(outcome==='ordinary')assert.equal(failure,ordinary);
 else if(outcome==='guest')assert.equal(failure,guest);
 else{assert.equal(failure,undefined);assert.equal(result.position,0);assert.deepEqual([...result.replacement],[63]);}
 rows.push({operation,outcome,cancel,passed:true});
}
const data=Buffer.alloc(4096),length=readSync(fd,data,0,data.length,0);
assert.equal(data.subarray(0,length).toString().trim().split('\n').length,16);
console.log(JSON.stringify({rows,realWrites:16,realReads:1,passed:rows.length},null,2));
}finally{closeSync(fd);rmSync(directory,{recursive:true});}
